def find_path(graph, start, goal):
    # Track the path from start to goal
    path = []
    # Track visited nodes
    visited = set()

    def search(node):
        if node == goal:
            path.append(goal)
            path.reverse()
            return True
        if node in visited:
            return False
        visited.add(node)
        for next_node in graph[node]:
            if search(next_node):
                path.append(node)
                return True
        return False

    if search(start):
        return path
    else:
        return None
