def find_path(graph, start, goal):
    """
    This function finds a path from start to goal in a directed graph.
    It returns a list of nodes (inclusive) from start to goal if a path exists, otherwise returns None.
    """
    if start == goal:
        return [start]

    visited = set()
    path_stack = [(start, [start])]  # (current_node, path)

    while path_stack:
        (current_node, path) = path_stack.pop()
        if current_node not in visited:
            visited.add(current_node)
            for next_node in graph[current_node]:
                if next_node == goal:
                    return path + [goal]
                else:
                    path_stack.append((next_node, path + [next_node]))
    return None
