from collections import deque

def find_path(graph, start, goal):
    # If the start and goal are the same, we have found a path of length 0.
    if start == goal:
        return [start]

    # Initialize the queue with a tuple (path, node), starting with just the start node.
    queue = deque([(deque([start]), start)])

    while queue:
        (path, current) = queue.popleft()

        # If the current node is the goal, we have found a path, so return it.
        if current == goal:
            return list(path)

        # Otherwise, add the neighbors of the current node to the queue.
        for neighbor in graph[current]:
            if neighbor not in path:
                queue.append((path + (neighbor,), neighbor))

    # If we reach here, it means the goal is unreachable.
    return None
